#include "services/addresses.h"
#include <iostream>
using namespace roots::gui;
int main(int argc,char** argv){if(argc!=4)return 2;ServerCandidate profile;profile.connection.port=uint16_t(std::stoi(argv[1]));profile.connection.credential.reference=argv[2];profile.wallet="address/札幌";profile.expected_genesis=std::string(64,'a');RefreshIdentity id{{*BackendSessionId::Make("connection-1"),{*Hash256::Parse(profile.expected_genesis)},*WalletId::Make("wallet"),*DocumentId::Make("wallet-document-1"),{5},{7}},profile,1};rpc::CookieCredentials credentials;rpc::Transport transport(credentials);std::stop_source stop;if(std::string(argv[3])=="cancel")stop.request_stop();const std::vector<std::string> known=std::string(argv[3])=="older-observed" || std::string(argv[3])=="unproven-observed"?std::vector<std::string>{"public0index0"}:std::vector<std::string>{};auto result=FetchAddresses(transport,id,stop.get_token(),{4,2,8},known);std::cout<<"{\"error\":"<<rpc::Quote(rpc::ErrorName(result.error))<<",\"snapshot\":"<<bool(result.snapshot);if(result.snapshot){const auto& s=*result.snapshot;std::cout<<",\"stable\":"<<s.stable<<",\"unmapped\":"<<s.unmapped<<",\"rows\":[";bool comma=false;for(const auto& r:s.rows){if(comma)std::cout<<',';comma=true;std::cout<<"{\"index\":"<<r.index<<",\"internal\":"<<r.internal<<",\"lookahead\":"<<r.lookahead<<",\"address\":"<<rpc::Quote(r.address)<<",\"script\":"<<rpc::Quote(r.script)<<'}';}std::cout<<"],\"reasons\":[";comma=false;for(const auto& d:s.descriptors){if(comma)std::cout<<',';comma=true;std::cout<<rpc::Quote(d.reason);}std::cout<<']';}std::cout<<"}\n";return 0;}
